/* @autogenerated */
package net.civeira.phylax.integrationtest.features.oauth.flow;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import io.quarkus.test.junit.QuarkusTest;
import io.restassured.RestAssured;
import io.restassured.response.Response;
import net.civeira.phylax.features.oauth.client.domain.ClientCredentials;
import net.civeira.phylax.integrationtest.features.oauth.fixtures.ClientKeys;
import net.civeira.phylax.integrationtest.features.oauth.fixtures.OidcTestFixtures;

/**
 * {@code private_key_jwt} client authentication (task 3.2): a valid assertion authenticates the
 * client at the token and revocation endpoints; a foreign signature, another audience, a long
 * lifetime, a replay, a request object used as assertion, or a secret for that client fail.
 */
@QuarkusTest
class ClientAssertionFlowTest extends OidcIntegrationTestBase {

  private static final String BASE = "/oauth/openid/" + OidcTestFixtures.TENANT;
  private static final String JWT_CLIENT = OidcTestFixtures.JWT_CLIENT_ID;

  private ClientKeys keys;

  @BeforeEach
  void registerKeys() {
    keys = ClientKeys.rsa("k1");
    clientStoreGateway.setJwksJson(keys.jwks());
  }

  private static String issuer() {
    return RestAssured.get(BASE + "/.well-known/openid-configuration").jsonPath()
        .getString("issuer");
  }

  private static Response clientCredentials(Map<String, String> auth) {
    Map<String, String> form = new HashMap<>(auth);
    form.put("grant_type", "client_credentials");
    return RestAssured.given().formParams(form).post(BASE + "/token");
  }

  private static Map<String, String> assertionParams(String jwt) {
    return Map.of("client_assertion_type", ClientCredentials.JWT_BEARER_ASSERTION,
        "client_assertion", jwt);
  }

  @Test
  void validAssertion_authenticatesTheClient_andWorksOnlyOnce() {
    String jwt = keys.assertion(JWT_CLIENT, issuer() + "/token");

    Response first = clientCredentials(assertionParams(jwt));
    Assertions.assertEquals(200, first.statusCode(), first.getBody().asString());
    Assertions.assertNotNull(first.jsonPath().getString("access_token"));

    Response replay = clientCredentials(assertionParams(jwt));
    Assertions.assertEquals(401, replay.statusCode());
    Assertions.assertEquals("invalid_client", replay.jsonPath().getString("error"));
  }

  @Test
  void assertion_withMatchingClientIdOrIssuerAudience_isAccepted() {
    Map<String, String> params =
        new HashMap<>(assertionParams(keys.assertion(JWT_CLIENT, issuer())));
    params.put("client_id", JWT_CLIENT);
    Assertions.assertEquals(200, clientCredentials(params).statusCode());

    Map<String, String> other =
        new HashMap<>(assertionParams(keys.assertion(JWT_CLIENT, issuer() + "/token")));
    other.put("client_id", OidcTestFixtures.CLIENT_ID);
    Assertions.assertEquals(401, clientCredentials(other).statusCode());
  }

  @Test
  void assertion_signedWithAnotherKey_isRejected() {
    String forged = ClientKeys.rsa("k1").assertion(JWT_CLIENT, issuer() + "/token");
    Assertions.assertEquals(401, clientCredentials(assertionParams(forged)).statusCode());
  }

  @Test
  void assertion_forAnotherAudience_isRejected() {
    String jwt = keys.assertion(JWT_CLIENT, "https://elsewhere.example/token");
    Assertions.assertEquals(401, clientCredentials(assertionParams(jwt)).statusCode());
    String otherTenant = keys.assertion(JWT_CLIENT,
        issuer().replace(OidcTestFixtures.TENANT, OidcTestFixtures.OTHER_TENANT) + "/token");
    Assertions.assertEquals(401, clientCredentials(assertionParams(otherTenant)).statusCode());
  }

  @Test
  void assertion_livingMoreThanAnHour_isRejected() {
    String jwt = keys.assertion(JWT_CLIENT, issuer() + "/token", UUID.randomUUID().toString(),
        2 * 3600, Map.of());
    Assertions.assertEquals(401, clientCredentials(assertionParams(jwt)).statusCode());
  }

  @Test
  void requestObject_cannotAuthenticateTheClient() {
    String jwt = keys.assertion(JWT_CLIENT, issuer(), UUID.randomUUID().toString(), 300,
        Map.of("response_type", "code", "client_id", JWT_CLIENT));
    Assertions.assertEquals(401, clientCredentials(assertionParams(jwt)).statusCode());
  }

  @Test
  void assertionClient_cannotUseASecret_norMixMethods() {
    Response secret =
        RestAssured.given().auth().preemptive().basic(JWT_CLIENT, OidcTestFixtures.CLIENT_SECRET)
            .formParam("grant_type", "client_credentials").post(BASE + "/token");
    Assertions.assertEquals(401, secret.statusCode());

    Map<String, String> mixed =
        new HashMap<>(assertionParams(keys.assertion(JWT_CLIENT, issuer() + "/token")));
    mixed.put("client_secret", OidcTestFixtures.CLIENT_SECRET);
    Assertions.assertEquals(401, clientCredentials(mixed).statusCode());

    Map<String, String> wrongType = Map.of("client_assertion_type", "urn:other", "client_assertion",
        keys.assertion(JWT_CLIENT, issuer() + "/token"));
    Assertions.assertEquals(401, clientCredentials(wrongType).statusCode());
  }

  @Test
  void assertion_authenticatesAtTheRevocationEndpoint() {
    String token = clientCredentials(assertionParams(keys.assertion(JWT_CLIENT, issuer())))
        .jsonPath().getString("access_token");
    Map<String, String> form =
        new HashMap<>(assertionParams(keys.assertion(JWT_CLIENT, issuer() + "/revocation")));
    form.put("token", token);
    Assertions.assertEquals(200,
        RestAssured.given().formParams(form).post(BASE + "/revocation").statusCode());
  }

  @Test
  void discovery_announcesPrivateKeyJwt_withoutClientSecretJwt() {
    Response discovery = RestAssured.get(BASE + "/.well-known/openid-configuration");
    for (String field : List.of("token_endpoint_auth_methods_supported",
        "introspection_endpoint_auth_methods_supported",
        "revocation_endpoint_auth_methods_supported")) {
      List<String> methods = discovery.jsonPath().getList(field);
      Assertions.assertTrue(methods.contains("private_key_jwt"), field);
      Assertions.assertFalse(methods.contains("client_secret_jwt"), field);
    }
    Assertions.assertEquals(List.of("RS256", "ES256"),
        discovery.jsonPath().getList("token_endpoint_auth_signing_alg_values_supported"));
  }
}
